from __future__ import annotations

from datetime import datetime, timezone

from gitseed.application import execute
from gitseed.collect.search import Candidate, CollectResult
from gitseed.evidence import ClaimBasis
from gitseed.grade.smoke import SmokeResult
from gitseed.grade.types import GradeResult
from gitseed.pipeline.run import FetchedFiles
from gitseed.ports import RepositoryMetadata, RunPorts, RunRequest
from gitseed.scoring import ScoreInputs


CANDIDATE = Candidate(
    "org/repo",
    "org",
    "https://example.test/org/repo",
    1,
    "2026-01-01T00:00:00Z",
)


class Repository:
    def search(self, query: str, limit: int) -> CollectResult:
        return CollectResult(candidates=[CANDIDATE])

    def metadata(self, candidate: Candidate, at: datetime) -> RepositoryMetadata:
        return RepositoryMetadata(ScoreInputs(None, None, None))


class Files:
    def read(self, candidate: Candidate) -> FetchedFiles:
        return FetchedFiles((("main.py", "pass\n"),))


class Model:
    def evaluate(self, digest: str) -> GradeResult:
        return GradeResult(1, 1, "ok", "fixture", 0.0, "v1")

    def flags_malicious(self, digest: str) -> bool:
        return False


class Clock:
    def now(self) -> datetime:
        return datetime(2026, 1, 1, tzinfo=timezone.utc)


class BrokenEvidenceReader:
    evidence_names = frozenset({"domain_status", "dependency_graph"})

    def read_evidence(
        self,
        candidate: Candidate,
        files: FetchedFiles,
        metadata: RepositoryMetadata | None,
    ):
        raise RuntimeError("evidence source unavailable")


def test_failed_custom_evidence_reader_preserves_its_vocabulary() -> None:
    artifact = execute(
        RunRequest("anything", 1),
        RunPorts(Repository(), Files(), Model(), Clock(), BrokenEvidenceReader()),
        model_smoke=SmokeResult(True, "fixture"),
    )

    evidence = artifact.repositories[0].category_evidence

    assert {item.evidence for item in evidence} == {
        "domain_status",
        "dependency_graph",
    }
    assert all(item.values == frozenset() for item in evidence)
    assert all(item.basis is ClaimBasis.ABSENT for item in evidence)
    assert any(failure.port == "category" and failure.operation == "read" for failure in artifact.failures)
